const fs = require('fs');
const path = require('path');
const dir = __dirname;

function tmpl(title, subtitle, questions) {
  const qs = JSON.stringify(questions);
  return `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>${title}</title><style>*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;background:#1a1a2e;color:#e0e0e0;min-height:100vh;padding:2rem 1rem}.container{max-width:800px;margin:0 auto}h1{text-align:center;margin-bottom:.5rem;font-size:1.8rem;color:#fff}.subtitle{text-align:center;color:#8892b0;margin-bottom:2rem;font-size:1rem}.progress-bar-container{background:#0d1117;border-radius:10px;height:14px;margin-bottom:2rem;overflow:hidden}.progress-bar{background:linear-gradient(90deg,#0d6efd,#4dabf7);height:100%;width:0%;border-radius:10px;transition:width .4s ease}.progress-text{text-align:center;color:#8892b0;margin-bottom:1rem;font-size:.9rem}.card{background:#16213e;border-radius:12px;padding:2rem;margin-bottom:1.5rem;box-shadow:0 4px 20px rgba(0,0,0,.3)}.question-label{font-size:.85rem;color:#4dabf7;text-transform:uppercase;letter-spacing:1px;margin-bottom:.5rem}.question-text{font-size:1.15rem;margin-bottom:1.2rem;line-height:1.5;color:#fff}pre{background:#0d1117;border:1px solid #30363d;border-radius:8px;padding:1rem;margin-bottom:1.2rem;overflow-x:auto;font-size:.95rem}code{font-family:'Consolas','Fira Code','Courier New',monospace;color:#c9d1d9}.options{list-style:none}.options li{margin-bottom:.5rem}.options label{display:flex;align-items:center;gap:.75rem;padding:.8rem 1rem;background:#0d1117;border:2px solid #30363d;border-radius:8px;cursor:pointer;transition:border-color .2s,background .2s;font-size:1rem}.options label:hover{border-color:#4dabf7;background:#1c2a4a}.options input[type=radio]{accent-color:#0d6efd;width:18px;height:18px;flex-shrink:0}.btn{display:inline-block;padding:.7rem 2rem;border:none;border-radius:8px;font-size:1rem;font-weight:600;cursor:pointer;transition:background .2s,transform .1s}.btn-primary{background:#0d6efd;color:#fff}.btn-primary:hover{background:#3b82f6}.btn-primary:disabled{background:#374151;cursor:not-allowed}.btn-restart{background:#238636;color:#fff;margin-top:1rem;padding:.7rem 2rem;border:none;border-radius:8px;font-size:1rem;font-weight:600;cursor:pointer}.btn-restart:hover{background:#2ea043}.feedback{margin-top:1rem;padding:1rem 1.2rem;border-radius:8px;font-size:.95rem;line-height:1.5;display:none}.feedback.correct{background:#0f5132;border:1px solid #198754;color:#d1fae5;display:block}.feedback.wrong{background:#842029;border:1px solid #dc3545;color:#fdd;display:block}.score-card{text-align:center;padding:3rem 2rem}.score-card .score{font-size:3rem;font-weight:700;color:#4dabf7;margin-bottom:.5rem}.score-card .score-label{font-size:1.2rem;color:#8892b0;margin-bottom:1.5rem}.hidden{display:none}</style></head><body><div class="container"><h1>${title}</h1><p class="subtitle">${subtitle}</p><div class="progress-bar-container"><div class="progress-bar" id="progressBar"></div></div><p class="progress-text" id="progressText">Question 1 / 5</p><div id="quizContainer"></div><div id="scoreContainer" class="card score-card hidden"></div></div><script>const questions=${qs};let currentQuestion=0,score=0,answered=false;function renderQuestion(){const q=questions[currentQuestion],total=questions.length;document.getElementById('progressBar').style.width=((currentQuestion/total)*100)+'%';document.getElementById('progressText').textContent=\`Question \${currentQuestion+1} / \${total}\`;let html=\`<div class="card"><p class="question-label">\${q.label}</p><p class="question-text">\${q.text}</p>\`;if(q.code)html+=\`<pre><code>\${q.code}</code></pre>\`;html+=\`<ul class="options">\`;q.options.forEach((opt,i)=>{html+=\`<li><label><input type="radio" name="q" value="\${i}"> \${opt}</label></li>\`;});html+=\`</ul><button class="btn btn-primary" id="validateBtn" onclick="validate()" disabled>Valider</button><div class="feedback" id="feedback"></div></div>\`;document.getElementById('quizContainer').innerHTML=html;document.querySelectorAll('input[name="q"]').forEach(r=>{r.addEventListener('change',()=>{document.getElementById('validateBtn').disabled=false;});});answered=false;}function validate(){if(answered){currentQuestion++;if(currentQuestion<questions.length)renderQuestion();else showScore();return;}answered=true;const selected=document.querySelector('input[name="q"]:checked');if(!selected)return;const val=parseInt(selected.value),q=questions[currentQuestion];const fb=document.getElementById('feedback'),btn=document.getElementById('validateBtn');document.querySelectorAll('input[name="q"]').forEach(r=>r.disabled=true);if(val===q.answer){score++;fb.className='feedback correct';fb.innerHTML=\`<strong>Correct !</strong> \${q.explanation}\`;}else{fb.className='feedback wrong';fb.innerHTML=\`<strong>Incorrect.</strong> \${q.explanation}\`;}btn.textContent=currentQuestion<questions.length-1?'Suivant':'Voir le score';}function showScore(){document.getElementById('quizContainer').classList.add('hidden');document.getElementById('progressBar').style.width='100%';document.getElementById('progressText').textContent='Termine !';const sc=document.getElementById('scoreContainer');sc.classList.remove('hidden');const pct=Math.round((score/questions.length)*100);let msg=pct===100?'Parfait !':pct>=60?'Bien joue !':'Continuez a reviser !';sc.innerHTML=\`<div class="score">\${score} / \${questions.length}</div><div class="score-label">\${msg} (\${pct}%)</div><button class="btn-restart" onclick="restart()">Recommencer</button>\`;}function restart(){currentQuestion=0;score=0;answered=false;document.getElementById('scoreContainer').classList.add('hidden');document.getElementById('quizContainer').classList.remove('hidden');renderQuestion();}renderQuestion();</script></body></html>`;
}

const quizzes = [
// === 04-02 migrations-versioning ===
{file:"quiz-04-02-migrations-versioning.html",title:"Migrations & Content Versioning",sub:"Module 04 — Architecture BDD",q:[
{label:"Question 1",text:"Qu'est-ce que la strategie Expand-Contract pour les migrations zero-downtime ?",options:["Ajouter une colonne, copier les donnees, supprimer l'ancienne dans un seul deploiement","Etendre le schema avec la nouvelle colonne + sync trigger, migrer le code, puis supprimer l'ancienne colonne sur 3 deploiements","Dupliquer la table entiere puis basculer les requetes","Creer une vue SQL qui masque le renommage"],answer:1,explanation:"Expand-Contract se fait en 3 deploiements : (1) ajouter la colonne + trigger sync, (2) deployer le code qui utilise la nouvelle colonne, (3) supprimer l'ancienne. Chaque migration est compatible avec la version N et N-1 du code."},
{label:"Question 2",text:"Pourquoi utiliser CREATE INDEX CONCURRENTLY en PostgreSQL ?",options:["Il cree l'index plus rapidement qu'un CREATE INDEX classique","Il permet de creer un index sans bloquer les lectures ni les ecritures sur la table","Il cree automatiquement un index partiel","Il replique l'index sur tous les read replicas"],answer:1,explanation:"CREATE INDEX CONCURRENTLY ne prend pas de verrou exclusif sur la table — les lectures et ecritures continuent normalement. Le trade-off : la creation est plus lente et consomme plus de ressources."},
{label:"Question 3",text:"Quel est l'avantage principal du content versioning diff-based par rapport aux snapshots complets ?",options:["Les diffs sont plus rapides a reconstruire que les snapshots","La reduction de stockage (~63-92%) car seules les differences sont conservees","Les diffs permettent le merge automatique de versions concurrentes","Les diffs eliminent le besoin de backups"],answer:1,explanation:"Un snapshot complet stocke tout le contenu a chaque version (3000 × N caracteres). Les diffs stockent uniquement les changements (~200 caracteres par version). Le trade-off : la reconstruction necessite de rejouer les diffs depuis le dernier snapshot."},
{label:"Question 4",text:"Lors d'une migration multi-tenant (schema-per-tenant), que faire si un tenant echoue ?",options:["Annuler toutes les migrations de tous les tenants (rollback global)","Arreter immediatement le processus et alerter","Rollback ce tenant uniquement, continuer les autres, et alerter le monitoring","Ignorer l'erreur et passer au tenant suivant sans logger"],answer:2,explanation:"On isole l'echec : rollback du tenant en erreur, mais on continue les autres pour ne pas bloquer tout le monde. L'alerte monitoring permet d'investiguer et corriger le tenant en erreur manuellement."},
{label:"Question 5",text:"Quand faut-il creer un nouveau snapshot dans le content versioning diff-based ?",options:["A chaque modification du contenu","Uniquement a la premiere version","Tous les N diffs (ex: toutes les 20 versions) pour limiter le temps de reconstruction","Seulement quand l'utilisateur le demande explicitement"],answer:2,explanation:"Sans snapshots intermediaires, reconstruire la version 100 necessite d'appliquer 99 diffs. En creant un snapshot toutes les 20 versions, on applique au maximum 19 diffs (~5ms). C'est un trade-off entre stockage (snapshots = plus gros) et performance de lecture."}
]},
// === 04-03 indexation-performance ===
{file:"quiz-04-03-indexation-performance.html",title:"Indexation & Performance",sub:"Module 04 — Architecture BDD",q:[
{label:"Question 1",text:"Quel type d'index PostgreSQL est le plus adapte pour le full-text search sur une colonne tsvector ?",options:["B-tree","Hash","GIN (Generalized Inverted Index)","BRIN (Block Range Index)"],answer:2,explanation:"Le GIN est un index inverse qui mappe chaque mot vers la liste des documents le contenant — ideal pour tsvector, JSONB et arrays. Le B-tree est pour l'egalite/plage, le BRIN pour les grandes tables ordonnees."},
{label:"Question 2",text:"Dans un EXPLAIN ANALYZE, que signale un Seq Scan sur une table de 500K lignes ?",options:["La requete est parfaitement optimisee","Un index manquant — la base parcourt toutes les lignes","Les statistiques de la table sont a jour","Le query planner a choisi la strategie la plus rapide"],answer:1,explanation:"Un Seq Scan sur une grande table signifie que PostgreSQL lit toutes les lignes faute d'index adapte. Ajouter un index transforme un Seq Scan (52ms) en Index Scan (8ms). Signal d'alerte : 'Rows Removed by Filter' eleve confirme le probleme."},
{label:"Question 3",text:"Quel est l'avantage principal d'un partial index ?",options:["Il indexe toutes les colonnes de la table automatiquement","Il est plus petit et plus rapide car il n'indexe qu'un sous-ensemble des lignes","Il remplace automatiquement les index existants","Il fonctionne sur tous les types de colonnes y compris JSONB"],answer:1,explanation:"Un partial index (ex: WHERE status = 'published') n'indexe que les lignes qui matchent le filtre. Si 40% des produits sont en draft, l'index est ~60% plus petit. Trade-off : il n'accelere que les requetes dont le WHERE correspond au filtre de l'index."},
{label:"Question 4",text:"A quoi sert un covering index (INCLUDE) en PostgreSQL ?",options:["A couvrir automatiquement toutes les requetes de la table","A inclure des colonnes non-filtrantes pour permettre un index-only scan sans lire la table","A creer un index sur plusieurs tables simultanement","A inclure les lignes supprimees dans l'index"],answer:1,explanation:"Un covering index inclut des colonnes supplementaires dans l'index. La requete peut etre satisfaite uniquement depuis l'index (index-only scan) sans acceder a la table (heap). Trade-off : l'index est plus gros, mais les lectures sont plus rapides."},
{label:"Question 5",text:"Pourquoi l'ordre des colonnes est-il important dans un index composite ?",options:["PostgreSQL trie toujours les colonnes par ordre alphabetique","Le prefixe de l'index peut etre utilise seul, mais pas les colonnes suivantes sans le prefixe","L'ordre n'a aucune importance, le query planner s'adapte","La premiere colonne doit toujours etre la cle primaire"],answer:1,explanation:"Un index (category_id, status) est utilisable pour WHERE category_id = X (prefixe) ou WHERE category_id = X AND status = Y, mais PAS pour WHERE status = Y seul. Regle : la colonne la plus selective en premier."}
]},
// === 04-04 patterns-lecture-ecriture ===
{file:"quiz-04-04-patterns-lecture-ecriture.html",title:"Patterns lecture / ecriture",sub:"Module 04 — Architecture BDD",q:[
{label:"Question 1",text:"Quel est le principal risque des read replicas avec replication asynchrone ?",options:["Les replicas ne peuvent pas etre indexees","Le read-your-own-writes problem : une lecture juste apres une ecriture peut ne pas voir la modification","Les replicas consomment plus de CPU que le master","Les replicas ne supportent pas les transactions"],answer:1,explanation:"La replication asynchrone a un lag de ~100ms. Si vous ecrivez sur le master puis lisez immediatement sur un replica, la modification peut ne pas etre visible. Solution : lire depuis le master pour les operations sensibles juste apres un write."},
{label:"Question 2",text:"Quelle est la difference entre une vue SQL classique et une vue materialisee ?",options:["La vue classique stocke les donnees, la materialisee ne les stocke pas","La vue materialisee stocke physiquement le resultat et peut etre indexee, contrairement a la vue classique","Les deux sont identiques en termes de performance","La vue materialisee est toujours en temps reel"],answer:1,explanation:"Une vue classique reexecute la requete a chaque appel. Une vue materialisee stocke le resultat physiquement (plus rapide) mais necessite un REFRESH pour se mettre a jour. Trade-off : performance lecture vs fraicheur des donnees."},
{label:"Question 3",text:"Quand doit-on denormaliser une base de donnees relationnelle ?",options:["Des le debut du projet pour anticiper les problemes de performance","Uniquement quand un JOIN est un bottleneck mesure, pas suppose","Quand la base depasse 1000 lignes","Jamais, la normalisation 3NF est toujours optimale"],answer:1,explanation:"La normalisation (3NF) est la regle par defaut. On denormalise quand un JOIN cause un probleme de performance MESURE. Trade-off : la denormalisation accelere les lectures mais complique les ecritures (mise a jour en N endroits) et la coherence."},
{label:"Question 4",text:"Dans le pattern cache-aside avec Redis, que se passe-t-il lors d'un cache miss ?",options:["Redis genere automatiquement la donnee manquante","L'API retourne une erreur 404","L'API lit la donnee depuis la DB, la retourne au client, et la stocke dans Redis pour les prochains appels","Le client doit renvoyer la requete apres un delai"],answer:2,explanation:"Cache-aside : (1) check cache Redis, (2) si miss → query DB (routee vers le replica), (3) stocker le resultat dans Redis avec un TTL, (4) retourner au client. Le prochain appel sera un cache hit."},
{label:"Question 5",text:"Quelle convention de namespace Redis est recommandee pour les cles de cache ?",options:["Des UUIDs aleatoires pour chaque cle","Le format {app}:{feature}:{key} (ex: shop:products:abc-123)","Le nom de la table SQL comme prefixe","Aucune convention, Redis gere le rangement automatiquement"],answer:1,explanation:"La convention {app}:{feature}:{key} permet un rangement logique, un scan par prefixe, et une invalidation groupee par tag ou feature. Exemple : shop:products:category:electronics pour une liste par categorie."}
]},
// === 04-05 nosql-polyglot-persistence ===
{file:"quiz-04-05-nosql-polyglot-persistence.html",title:"NoSQL & Polyglot Persistence",sub:"Module 04 — Architecture BDD",q:[
{label:"Question 1",text:"Quelle est la regle d'or concernant le choix entre PostgreSQL et NoSQL ?",options:["Toujours utiliser MongoDB pour les nouvelles applications","PostgreSQL est le choix par defaut — introduire du NoSQL seulement quand un besoin specifique le justifie","Toujours utiliser au moins 3 bases differentes pour la resilience","Le NoSQL est toujours plus performant que le relationnel"],answer:1,explanation:"PostgreSQL couvre 90% des cas (relations, ACID, FTS). On ajoute du NoSQL quand un besoin specifique l'exige : latence &lt;1ms (Redis), recherche avancee (Elasticsearch), ecriture massive (Cassandra). Chaque base supplementaire = cout ops."},
{label:"Question 2",text:"Quel est le principal inconvenient du polyglot persistence ?",options:["Les bases NoSQL ne supportent pas le chiffrement","Chaque base supplementaire necessite monitoring, backup et expertise — charge ops non negligeable","Il est impossible de faire communiquer des bases differentes","Le polyglot persistence viole les principes SOLID"],answer:1,explanation:"Le polyglot persistence (PG + Redis + Elasticsearch + S3) optimise chaque besoin, mais chaque base supplementaire = monitoring, backup, expertise, maintenance. Une equipe de 4 ne devrait pas gerer 5 bases differentes."},
{label:"Question 3",text:"Pour quels cas d'usage Redis est-il le meilleur choix ?",options:["Transactions ACID complexes multi-tables","Donnees ephemeres : sessions, cache, paniers temporaires — grace a sa latence &lt;1ms et son TTL","Stockage de fichiers binaires volumineux","Relations complexes entre entites (graphes)"],answer:1,explanation:"Redis excelle pour les donnees temporaires a acces ultra-rapide : sessions (TTL 30min), paniers (TTL 7j), cache produits (TTL 5min). Son modele key-value avec latence &lt;1ms est ideal. Il n'est pas adapte aux relations complexes ni au stockage massif."},
{label:"Question 4",text:"Quand une base de donnees graphe (Neo4j) est-elle justifiee ?",options:["Quand les donnees depassent 10 millions de lignes","Quand les relations entre entites SONT la donnee principale (reseau social, recommandations, detection de fraude)","Quand on a besoin de transactions ACID","Quand l'equipe est petite et veut simplifier l'architecture"],answer:1,explanation:"Les bases graphes excellentes quand les traversals de relations sont le coeur du besoin (amis d'amis, chemins, clusters). Trade-off : le scaling horizontal est difficile, et pour des requetes simples un SQL JOIN suffit."},
{label:"Question 5",text:"Dans l'architecture ShopArch, pourquoi le panier est-il dans Redis et pas dans PostgreSQL ?",options:["PostgreSQL ne supporte pas le type JSON pour les paniers","Le panier est temporaire (TTL 7 jours), necessite une latence &lt;1ms, et n'a pas besoin de transactions ACID","Redis offre une meilleure integrite transactionnelle que PostgreSQL","Le panier contient trop de donnees pour PostgreSQL"],answer:1,explanation:"Le panier est ephemere (TTL 7j), lu/ecrit a chaque interaction utilisateur (latence critique), et ne necessite pas de relations complexes. Redis est ideal. Les commandes finalisees, elles, vont dans PostgreSQL pour l'ACID et l'historique."}
]},
// === 04-06 search-architecture ===
{file:"quiz-04-06-search-architecture.html",title:"Search Architecture",sub:"Module 04 — Architecture BDD",q:[
{label:"Question 1",text:"A partir de quel volume de donnees Elasticsearch devient-il preferable a PostgreSQL FTS ?",options:["Des 1000 lignes","Au-dela de ~500K lignes, ou quand on a besoin de fuzzy search, facettes et suggestions","Elasticsearch est toujours preferable, meme pour de petits volumes","PostgreSQL FTS n'existe pas, il faut toujours Elasticsearch"],answer:1,explanation:"PostgreSQL FTS (tsvector + GIN) suffit pour 10K-500K lignes avec zero infra supplementaire. Elasticsearch apporte fuzzy search, facettes, suggestions et autocomplete avancee, mais avec un cout ops (cluster dedie). Trade-off : complexite ops vs richesse fonctionnelle."},
{label:"Question 2",text:"Pourquoi utiliser une interface SearchProvider plutot que coupler directement le code a Elasticsearch ?",options:["Elasticsearch n'a pas d'API stable","Le SearchProvider permet de swapper le moteur de recherche sans modifier le code metier (Dependency Inversion)","L'interface est obligatoire pour des raisons de securite","Le SearchProvider est plus rapide qu'un appel direct"],answer:1,explanation:"L'abstraction SearchProvider respecte le Dependency Inversion Principle : le code metier depend d'une interface, pas d'une implementation. On peut migrer de PG FTS vers Elasticsearch (ou Meilisearch) sans toucher au code appelant. Facilite aussi les tests (mock du provider)."},
{label:"Question 3",text:"Quelle est la difference entre la recherche keyword (BM25) et la recherche vector (embeddings) ?",options:["BM25 comprend le sens semantique, les embeddings comparent les mots exacts","BM25 compare les mots exacts (lexical), les embeddings comprennent le sens semantique via des vecteurs","Les deux sont identiques en termes de resultats","BM25 est toujours superieur aux embeddings"],answer:1,explanation:"BM25 cherche des correspondances lexicales exactes. Le vector search encode le sens dans un espace vectoriel — 'vetement chaud hiver' trouve 'doudoune' meme sans le mot exact. La fusion RRF (Reciprocal Rank Fusion) combine les deux pour le meilleur des deux mondes."},
{label:"Question 4",text:"Pourquoi appliquer un debounce de 300ms sur la recherche front-end ?",options:["Pour ralentir l'interface et eviter les clics accidentels","Pour ne pas envoyer une requete a chaque frappe clavier, ce qui surchargerait le serveur","Pour respecter le rate limiting de l'API","Le debounce est obligatoire pour le SEO"],answer:1,explanation:"Sans debounce, taper 'chaussure' envoie 9 requetes (une par lettre). Avec un debounce de 300ms, on attend que l'utilisateur arrete de taper avant d'envoyer UNE seule requete. Combine avec AbortController pour annuler les requetes precedentes."},
{label:"Question 5",text:"A quoi servent les weights (A, B, C, D) dans PostgreSQL full-text search ?",options:["A definir les permissions d'acces par role","A booster certains champs dans le ranking : un match dans le titre (A) vaut plus qu'un match dans la description (B)","A limiter le nombre de resultats par categorie","A configurer la langue du stemming"],answer:1,explanation:"Les weights permettent le boosting : setweight(to_tsvector('french', name), 'A') donne plus de poids au titre qu'a la description (B) ou la categorie (C). Ainsi, un produit dont le TITRE matche la recherche apparait avant un produit ou seule la description matche."}
]},
// === 05-01 component-architecture ===
{file:"quiz-05-01-component-architecture.html",title:"Component Architecture",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Qu'est-ce qu'un composant headless et quel est son principal avantage ?",options:["Un composant sans JavaScript, uniquement en CSS","Un composant qui encapsule la logique (etat, interactions, a11y) sans imposer de rendu visuel — reutilisable avec n'importe quel design","Un composant invisible utilise uniquement pour le SEO","Un composant qui ne s'affiche que cote serveur"],answer:1,explanation:"Un headless component (ou custom hook) separe la logique du rendu. Par exemple, useToggle() gere l'etat ouvert/ferme et l'accessibilite, mais le consommateur decide du JSX. Trade-off : plus de flexibilite mais plus de code chez le consommateur."},
{label:"Question 2",text:"Quel est le role d'un Error Boundary dans une application React ?",options:["Valider les props des composants au build time","Capturer les erreurs dans son sous-arbre et afficher un fallback au lieu de crasher toute l'application","Empecher les erreurs reseau","Logger automatiquement les erreurs dans Sentry"],answer:1,explanation:"Un Error Boundary capture les erreurs de rendu dans son sous-arbre et affiche un fallback (message d'erreur, bouton retry). C'est la graceful degradation cote front — une erreur dans un widget ne casse pas la page entiere. Trade-off : ne capture pas les erreurs async ni les event handlers."},
{label:"Question 3",text:"Dans l'Atomic Design, quelle est la hierarchie des niveaux de composants ?",options:["Pages → Templates → Modules → Widgets","Atoms → Molecules → Organisms → Templates → Pages","Components → Containers → Views → Layouts","Elements → Blocks → Sections → Screens"],answer:1,explanation:"Atomic Design (Brad Frost) : Atoms (bouton, input), Molecules (champ + label), Organisms (formulaire complet), Templates (layout de page), Pages (templates avec donnees). Chaque niveau compose le precedent."},
{label:"Question 4",text:"Pourquoi privilegier la composition de composants plutot que l'heritage ?",options:["L'heritage est plus rapide a l'execution","La composition permet de combiner des comportements independants sans creer de hierarchies rigides","L'heritage n'existe pas en JavaScript","La composition consomme moins de memoire"],answer:1,explanation:"La composition (children, render props, hooks) permet de combiner des comportements librement. L'heritage cree des hierarchies rigides difficiles a modifier. React privilegie explicitement 'composition over inheritance'. Trade-off : la composition peut necessiter plus de boilerplate."},
{label:"Question 5",text:"Qu'est-ce que le pattern 'component registry' et quand l'utiliser ?",options:["Un registre npm prive pour les composants internes","Un objet qui mappe des noms de composants a leurs implementations, utile pour le rendu dynamique (CMS, plugins)","Un fichier CSS global qui reference tous les composants","Un outil de documentation automatique des composants"],answer:1,explanation:"Le component registry permet de resoudre dynamiquement un composant par son nom (ex: le CMS stocke 'HeroBlock' en DB et le registry retourne le composant React correspondant). Essentiel pour les systemes extensibles (CMS, plugins)."}
]},
// === 05-02 state-management ===
{file:"quiz-05-02-state-management.html",title:"State Management Patterns",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Quelle est la regle d'or pour choisir ou placer l'etat dans une application React ?",options:["Toujours utiliser un store global pour tout l'etat","Utiliser le scope le plus petit possible — global seulement quand necessaire","Stocker tout l'etat dans l'URL pour le SEO","Utiliser localStorage pour tout l'etat persistant"],answer:1,explanation:"80% de l'etat est local (useState). Le store global (Zustand, Redux) est reserve a l'etat partage app-wide (user connecte, panier, theme). Les donnees serveur vivent dans React Query/SWR. L'URL stocke filtres et pagination."},
{label:"Question 2",text:"Pourquoi les donnees serveur (produits, commandes) devraient-elles etre gerees par React Query/SWR plutot que par un store Redux ?",options:["Redux ne supporte pas les appels API","React Query gere automatiquement le cache, la revalidation, les retries et le stale-while-revalidate","React Query est plus rapide que Redux","Redux sera bientot deprecie"],answer:1,explanation:"React Query/SWR sont concus pour les donnees serveur : cache automatique, invalidation, SWR, retry, deduplication de requetes. Redux necessite d'ecrire tout ce boilerplate manuellement. Trade-off : React Query ne gere pas l'etat client (UI, formulaires)."},
{label:"Question 3",text:"Comment synchroniser l'etat entre plusieurs onglets du navigateur ?",options:["C'est impossible, chaque onglet est completement isole","En utilisant BroadcastChannel pour envoyer des messages entre onglets du meme domaine","En faisant un polling HTTP toutes les secondes","En partageant un Web Worker entre les onglets"],answer:1,explanation:"BroadcastChannel permet la communication entre onglets du meme domaine. Quand le theme change dans un onglet, un postMessage notifie les autres. Utilise pour synchroniser le theme, la locale, et les evenements de logout."},
{label:"Question 4",text:"Qu'est-ce que le 'derived state' et pourquoi eviter de le stocker ?",options:["Un etat qui derive d'un autre etat et doit etre stocke separement pour la performance","Un etat calcule a partir d'un autre etat — il ne doit pas etre stocke car il se desynchronise","Un etat herite du composant parent","Un etat qui ne change jamais"],answer:1,explanation:"Le derived state (computed/selector) se calcule a partir de l'etat source. Le stocker cree un risque de desynchronisation. Exemple : totalPanier = somme(items.prix × items.quantite) — c'est un calcul, pas un etat a stocker."},
{label:"Question 5",text:"Ou stocker les tokens d'authentification cote front-end ?",options:["Dans localStorage pour la persistance entre sessions","Dans un cookie httpOnly via un BFF (ou en SessionStorage a defaut) — jamais dans localStorage","Dans une variable globale JavaScript","Dans le store Redux pour un acces facile"],answer:1,explanation:"localStorage est accessible par n'importe quel script JS — une faille XSS permet de voler le token. Un cookie httpOnly n'est pas accessible en JS. SessionStorage est vide a l'ouverture d'un nouvel onglet, limitant la surface d'attaque. Le BFF est la solution la plus sure."}
]},
// === 05-03 routing-navigation ===
{file:"quiz-05-03-routing-navigation.html",title:"Routing & Navigation",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Pourquoi le code splitting par route est-il important pour la performance ?",options:["Il permet de charger toutes les routes en parallele","Chaque route charge son code a la demande — l'utilisateur ne telecharge pas l'admin quand il visite le catalogue","Il ameliore le SEO en generant des URLs propres","Il simplifie le routing cote serveur"],answer:1,explanation:"Sans code splitting, le bundle contient TOUTES les routes (catalogue + admin + checkout). Avec le split, seul le code de la route visitee est charge. Le reste est telecharge a la demande. Trade-off : un leger delai au premier chargement de chaque route."},
{label:"Question 2",text:"Pourquoi l'ordre des route guards est-il critique ?",options:["L'ordre n'a pas d'importance, les guards sont independants","Chaque guard depend du precedent : session → auth → RBAC → titre. Inverser l'ordre cause des redirections inutiles","Les guards doivent etre tries par ordre alphabetique","Le premier guard qui passe court-circuite les suivants"],answer:1,explanation:"On doit d'abord restaurer la session (async), puis verifier l'authentification, puis le RBAC, puis mettre a jour le titre. Si on verifie le RBAC avant la session, un utilisateur avec un token valide sera redirige vers /login inutilement."},
{label:"Question 3",text:"D'ou doivent provenir les breadcrumbs et pourquoi ?",options:["Du menu de navigation principal","De la hierarchie des routes, car les routes sont stables et refletent la vraie structure de navigation","D'une API backend dediee","Du titre de la page courante"],answer:1,explanation:"Les menus peuvent changer independamment de la structure des pages. Les routes sont stables et refletent la hierarchie reelle. On genere les breadcrumbs automatiquement via useMatches(). Trade-off : necessite une bonne architecture de routes imbriquees."},
{label:"Question 4",text:"Qu'est-ce que le RouteMeta typing et a quoi sert-il ?",options:["Un type TypeScript qui attache des metadonnees (roles, titre, layout) a chaque route pour le RBAC et le SEO","Un outil de documentation automatique des routes","Un format de metadonnees pour le sitemap XML","Un middleware serveur pour le routing"],answer:0,explanation:"Le RouteMeta est un type TypeScript attache a chaque route : roles autorises, titre de la page, layout a utiliser. Les guards lisent ces meta pour prendre leurs decisions (redirection si role insuffisant, mise a jour du titre)."},
{label:"Question 5",text:"Comment gerer les routes protegees pour le SEO ?",options:["Indexer toutes les routes, y compris les pages protegees","Les routes protegees doivent retourner un 403 ou un redirect 302 vers /login pour les crawlers, et ne pas etre dans le sitemap","Utiliser un robot.txt pour bloquer toutes les routes","Dupliquer le contenu protege dans une version publique"],answer:1,explanation:"Les pages protegees ne doivent pas etre indexees (pas dans le sitemap, noindex si accessible). Un crawler qui arrive sur /admin doit recevoir un 302 vers /login ou un 403. Le contenu protege ne doit jamais fuiter dans les resultats de recherche."}
]},
// === 05-04 data-fetching-patterns ===
{file:"quiz-05-04-data-fetching-patterns.html",title:"Data Fetching Patterns",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Pourquoi utiliser un AbortController lors du unmount d'un composant React ?",options:["Pour accelerer le demontage du composant","Pour annuler les requetes en cours et eviter les memory leaks et les mises a jour d'etat sur un composant demonte","Pour liberer la memoire du DOM","Pour empecher le re-render du composant"],answer:1,explanation:"Sans annulation, la reponse arrive et tente de mettre a jour un etat qui n'existe plus (composant demonte) → memory leak et erreur React. AbortController annule proprement la requete HTTP quand le composant disparait."},
{label:"Question 2",text:"Qu'est-ce que le pattern Stale-While-Revalidate (SWR) ?",options:["Rejeter les donnees en cache et toujours recharger depuis le serveur","Servir les donnees en cache immediatement (meme si potentiellement obsoletes), puis revalider en background","Stocker les donnees dans le Service Worker pour un acces offline","Invalider le cache toutes les 5 minutes"],answer:1,explanation:"SWR sert les donnees en cache en 0ms (l'utilisateur voit le contenu immediatement) puis revalide en background. Si les donnees ont change, l'UI se met a jour silencieusement. Trade-off : l'utilisateur voit brievement des donnees potentiellement obsoletes."},
{label:"Question 3",text:"Pourquoi ne faut-il jamais retrier les erreurs HTTP 4xx (sauf 429) ?",options:["Les erreurs 4xx sont toujours temporaires et se resolvent seules","Les erreurs 4xx sont des erreurs client (requete malformee, non autorise) — retrier ne changera rien","Le retry des 4xx est bloque par les navigateurs","Les erreurs 4xx indiquent un probleme reseau"],answer:1,explanation:"400 (bad request), 401 (non authentifie), 403 (interdit), 404 (introuvable) sont des erreurs client — la meme requete donnera le meme resultat. Seul 429 (rate limiting) merite un retry apres le delai Retry-After. Les 5xx (erreur serveur) sont retriables."},
{label:"Question 4",text:"Quel est le role de la request priority dans le data fetching ?",options:["Definir l'ordre d'affichage des donnees dans l'UI","Prioriser les requetes critiques (contenu above-the-fold) et differer les secondaires (analytics, below-the-fold)","Limiter le nombre de requetes simultanees a 6","Definir la taille maximale des reponses"],answer:1,explanation:"Les requetes critiques (header, hero, produit principal) doivent passer avant les secondaires (recommandations, analytics). On utilise fetchpriority='high' pour le LCP et on differe les requetes basse priorite avec requestIdleCallback ou Intersection Observer."},
{label:"Question 5",text:"Comment implementer un retry avec exponential backoff ?",options:["Retrier immediatement 10 fois de suite","Attendre 1s, puis 2s, puis 4s entre chaque retry, avec un maximum de tentatives","Doubler le timeout de la requete a chaque tentative","Envoyer la requete a un serveur de fallback"],answer:1,explanation:"Exponential backoff : delai = baseDelay × 2^attempt (1s, 2s, 4s...) + jitter aleatoire pour eviter le thundering herd. Maximum 2-3 retries. Cela laisse le temps au serveur de se retablir sans le surcharger."}
]},
// === 05-05 design-tokens-systems ===
{file:"quiz-05-05-design-tokens-systems.html",title:"Design Tokens & Design Systems",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Quels sont les 3 niveaux de token layering dans un design system ?",options:["Small, Medium, Large","Global (valeurs brutes), Semantique (intentions), Composant (specifique)","Primary, Secondary, Tertiary","CSS, JavaScript, HTML"],answer:1,explanation:"Global (--color-blue-500), Semantique (--color-primary = blue-500), Composant (--button-bg = --color-primary). Pour le dark mode, on change uniquement le niveau semantique. Trade-off : plus de niveaux = plus de flexibilite mais plus d'indirection."},
{label:"Question 2",text:"Pourquoi OKLCH est-il prefere a HSL pour generer des palettes de couleurs ?",options:["OKLCH est plus rapide a calculer que HSL","OKLCH est perceptuellement uniforme : deux couleurs avec la meme lightness ont reellement la meme luminosite percue par l'oeil","OKLCH supporte plus de couleurs que HSL","OKLCH est le seul format supporte par les navigateurs modernes"],answer:1,explanation:"En HSL, un jaune a 50% de lightness parait beaucoup plus clair qu'un bleu a 50%. OKLCH est perceptuellement uniforme — les palettes generees sont visuellement coherentes et accessibles. Trade-off : syntaxe plus complexe et support navigateur recent."},
{label:"Question 3",text:"Comment implementer le dark mode avec des design tokens ?",options:["Dupliquer tous les fichiers CSS avec des valeurs differentes","Changer les associations du niveau semantique (--color-surface passe de blanc a gris fonce) sans modifier les tokens composant","Utiliser un filtre CSS invert(1) sur toute la page","Creer un theme completement separe avec ses propres composants"],answer:1,explanation:"Le dark mode change uniquement le mapping semantique : --color-surface: var(--gray-900) au lieu de var(--white). Les tokens composant (--card-bg: var(--color-surface)) restent identiques. Trade-off : necessite une bonne architecture de tokens des le depart."},
{label:"Question 4",text:"Quel est le role du pipeline de build des design tokens ?",options:["Minifier le CSS en production","Transformer la source JSON en CSS custom properties et types TypeScript, garantissant la coherence entre design et code","Generer automatiquement les composants React","Deployer les tokens sur un CDN"],answer:1,explanation:"Le pipeline (generate-tokens.mjs) prend les fichiers JSON source et genere les CSS custom properties (--color-blue-500: oklch(...)) + les types TypeScript. La source de verite est le JSON, tout le reste est derive."},
{label:"Question 5",text:"Pourquoi limiter les fonts a 2-3 fichiers et ~100KB maximum ?",options:["Les navigateurs ne supportent que 3 fichiers de police","Les fonts sont des ressources render-blocking qui retardent le First Contentful Paint","Les fonts ne sont pas mises en cache par le navigateur","Les fonts ne fonctionnent pas sur les appareils mobiles"],answer:1,explanation:"Chaque fichier de police est une ressource qui bloque le rendu (render-blocking) ou cause un Flash Of Unstyled Text (FOUT). Plus de fonts = plus de poids = TTFB et FCP degrades. Trade-off : richesse typographique vs performance."}
]},
// === 05-06 strategies-de-rendu ===
{file:"quiz-05-06-strategies-de-rendu.html",title:"Strategies de rendu (SSR, SSG, ISR)",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Quelle strategie de rendu offre le meilleur TTFB pour un site e-commerce ?",options:["SPA (Single Page Application)","SSR (Server-Side Rendering) pour chaque requete","SSG (Static Site Generation) ou ISR servis depuis un CDN (~50ms)","CSR (Client-Side Rendering) avec un gros bundle JS"],answer:2,explanation:"SSG/ISR pre-generent le HTML au build time ou a la demande, puis le cachent sur CDN. TTFB ~50ms vs ~200-600ms pour SSR. Trade-off : SSG est statique (necessite un rebuild pour changer), ISR offre un compromis (quasi temps reel + cache CDN)."},
{label:"Question 2",text:"Quel est le principal probleme du SPA pour le SEO ?",options:["Les SPA ne supportent pas les meta tags","Le HTML initial est vide — les moteurs de recherche voient une page blanche sans contenu","Les SPA sont trop lentes pour etre indexees","Les SPA ne supportent pas HTTPS"],answer:1,explanation:"En SPA, le navigateur recoit un HTML quasi vide et le JavaScript genere le contenu. Les crawlers voient une page blanche (malgre l'amelioration de Googlebot). SSR/SSG resolvent ce probleme en envoyant du HTML complet des le premier rendu."},
{label:"Question 3",text:"Qu'est-ce que l'hydration et quel est son cout ?",options:["Le processus de compression du HTML pour le transfert reseau","Le processus par lequel React attache les event handlers au HTML genere cote serveur, ce qui consomme du CPU client","Le chargement des images en lazy loading","La mise en cache du HTML dans le Service Worker"],answer:1,explanation:"L'hydration reconcilie le HTML statique (SSR) avec le Virtual DOM React. React parcourt le DOM, attache les handlers, et rend la page interactive. Trade-off : le HTML est visible immediatement (bon TTFB) mais l'interactivite arrive apres l'hydration (TTI)."},
{label:"Question 4",text:"Qu'est-ce que le Personalization Shell Pattern ?",options:["Un framework pour creer des composants personnalises","Servir une page publique CDN-cacheable avec des skeletons, puis charger le contenu personnalise cote client apres hydration","Un outil de theming dynamique","Un pattern de routing pour les pages protegees"],answer:1,explanation:"Le shell pattern sert du HTML public (CDN-cacheable) avec des zones vides (skeletons) pour le contenu personnalise (panier, menu user). Apres hydration, le client fetch les donnees privees. Cela evite le header Vary: Cookie qui tue le cache CDN."},
{label:"Question 5",text:"Quand choisir ISR (Incremental Static Regeneration) plutot que SSR pur ?",options:["Quand le contenu change toutes les secondes","Quand le contenu change regulierement mais pas a chaque requete — ISR offre le cache CDN avec une revalidation periodique","Quand on n'a pas besoin de SEO","Quand l'application est une SPA sans serveur"],answer:1,explanation:"ISR combine le meilleur de SSG (cache CDN, TTFB ~50ms) et SSR (donnees quasi temps reel). La page est regenaree en background selon un timer ou on-demand. Trade-off : les utilisateurs peuvent voir une version legerement obsolete pendant la regeneration."}
]},
// === 05-07 performance-frontend ===
{file:"quiz-05-07-performance-frontend.html",title:"Performance Front-end",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Quels sont les 3 Core Web Vitals mesures par Google ?",options:["TTFB, FCP, TTI","LCP (&lt;2.5s), CLS (&lt;0.1), INP (&lt;200ms)","DNS, TCP, TLS","FPS, RAM, CPU"],answer:1,explanation:"LCP (Largest Contentful Paint) mesure le temps de rendu du plus grand element visible. CLS (Cumulative Layout Shift) mesure la stabilite visuelle. INP (Interaction to Next Paint) mesure la reactivite. Ces 3 metriques impactent le ranking Google."},
{label:"Question 2",text:"Pourquoi le JavaScript est-il le contenu le plus couteux a charger ?",options:["Le JavaScript est plus volumineux que les images","Le JavaScript necessite parsing + compilation + execution, alors que le HTML/CSS est seulement parse","Les navigateurs limitent le JavaScript a un seul thread","Le JavaScript n'est pas compressible"],answer:1,explanation:"200KB de JS != 200KB d'image. Le JS doit etre telecharge, parse, compile (JIT) et execute — chaque etape consomme du CPU. Une image est juste decodee et affichee. C'est pourquoi le budget JS (200KB gzip) est strict."},
{label:"Question 3",text:"A quoi sert un performance budget ?",options:["A limiter le nombre de developpeurs sur un projet","A definir des seuils maximaux (JS &lt; 200KB, TTFB &lt; 600ms) qui declenchent une alerte si depasses","A mesurer la productivite de l'equipe","A definir le budget infrastructure cloud"],answer:1,explanation:"Le performance budget definit des seuils (HTML ≤ 80KB gzip, JS ≤ 200KB, images ≤ 500KB par page). Si un build depasse un seuil, le CI echoue. Cela empeche la regression de performance au fil des features."},
{label:"Question 4",text:"Quelle est la strategie optimale pour charger les images below the fold ?",options:["Charger toutes les images en eager au chargement de la page","Utiliser loading='lazy' avec des dimensions explicites (width/height) pour eviter le CLS","Ne pas afficher d'images below the fold","Utiliser uniquement des SVG pour toutes les images"],answer:1,explanation:"loading='lazy' differe le chargement des images hors viewport. Les dimensions explicites (width/height ou aspect-ratio) reservent l'espace et evitent le CLS. L'image LCP (above the fold) doit etre en eager avec fetchpriority='high'."},
{label:"Question 5",text:"Pourquoi separer les vendor chunks par nom (react, router, i18n) plutot qu'un seul vendor.js ?",options:["Pour simplifier le debogage en production","Pour que les dependances stables restent en cache navigateur meme quand le code applicatif change","Pour reduire la taille totale du bundle","Pour permettre le tree shaking des dependances"],answer:1,explanation:"Les dependances (react, router) changent rarement. En les separant, le cache navigateur les conserve meme quand le code app change (frequent). Avec un seul vendor.js, TOUT le cache est invalide a chaque build. Trade-off : plus de fichiers HTTP (neglige avec HTTP/2)."}
]},
// === 05-08 i18n-seo-architecture ===
{file:"quiz-05-08-i18n-seo-architecture.html",title:"i18n & SEO Architecture",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Quelle est la difference entre 'UI locale' et 'content locale' en i18n ?",options:["Ce sont deux noms pour le meme concept","L'UI locale est la langue de l'interface (boutons, menus), la content locale est la langue du contenu metier (articles, produits) — les deux sont independants","L'UI locale est geree cote serveur, la content locale cote client","L'UI locale est toujours en anglais"],answer:1,explanation:"Un editeur francophone peut vouloir l'interface en francais (UI locale = fr) mais editer un contenu en anglais (content locale = en). Les deux concepts sont independants et geres differemment (framework i18n vs MultiLangField JSONB)."},
{label:"Question 2",text:"A quoi sert le tag hreflang dans le HTML pour le SEO multilangue ?",options:["A traduire automatiquement le contenu de la page","A indiquer aux moteurs de recherche les versions linguistiques alternatives d'une page","A definir la police de caracteres par langue","A configurer le fallback de langue cote serveur"],answer:1,explanation:"hreflang dit a Google : 'cette page existe aussi en anglais a cette URL'. Google affiche la bonne version selon la langue de l'utilisateur. Sans hreflang, Google peut considerer les versions comme du contenu duplique."},
{label:"Question 3",text:"Qu'est-ce que le redirect chain collapsing et pourquoi est-il important ?",options:["Une technique de compression des redirections HTTP","Mettre a jour les anciens redirects pour pointer directement vers la destination finale, evitant les chaines A→B→C→D","Un outil de test des redirections","Une methode pour supprimer les redirections inutiles"],answer:1,explanation:"Quand un slug est modifie plusieurs fois (/a→/b→/c→/d = 3 hops), Google penalise les chaines > 2 redirects et chaque hop ajoute un round-trip. Le collapsing met a jour pour pointer directement : /a→/d, /b→/d, /c→/d."},
{label:"Question 4",text:"Pourquoi utiliser une URL canonique (rel=canonical) ?",options:["Pour accelerer le chargement de la page","Pour indiquer a Google quelle est la version de reference quand le meme contenu est accessible via plusieurs URLs","Pour creer des redirections automatiques","Pour empecher l'indexation de la page"],answer:1,explanation:"Si un produit est accessible via /products/123 et /promo/summer/123, le canonical indique a Google laquelle est la version de reference. Sans canonical, Google peut considerer les deux comme du contenu duplique et diluer le ranking."},
{label:"Question 5",text:"Quelle structure d'URL est recommandee pour un site multilangue ?",options:["Des query parameters (?lang=fr)","Des sous-repertoires par langue (/fr/produits, /en/products) — bons pour le SEO et simples a gerer","Des sous-domaines (fr.example.com, en.example.com)","Aucune structure specifique, tout dans la meme URL"],answer:1,explanation:"Les sous-repertoires (/fr/, /en/) partagent l'autorite du domaine, sont simples a deployer et a gerer, et bien compris par Google. Les sous-domaines sont plus lourds a maintenir (DNS, certificats). Les query params sont mal indexes."}
]},
// === 05-09 micro-frontends ===
{file:"quiz-05-09-micro-frontends.html",title:"Micro-frontends",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Quand NE PAS utiliser des micro-frontends ?",options:["Quand on a plus de 10 developpeurs","Quand l'equipe fait &lt; 5 devs, un seul domaine metier, stack homogene ou pour un MVP — le cout d'orchestration ne se justifie pas","Quand on utilise React","Quand l'application a plus de 50 pages"],answer:1,explanation:"Les micro-frontends resolvent des problemes organisationnels (deploiement independant, autonomie d'equipe). Avec une petite equipe et un seul domaine, le monolithe est plus simple. Le cout d'orchestration (communication inter-apps, shared deps) est significatif."},
{label:"Question 2",text:"Quel pattern de communication est recommande entre micro-frontends ?",options:["Un store Redux global partage entre toutes les apps","Des Custom Events (window.dispatchEvent) avec la convention {app}:{domain}:{action}","Des appels HTTP entre micro-frontends","Un WebSocket partage entre toutes les apps"],answer:1,explanation:"Les Custom Events offrent un decouplage total — l'emetteur ne connait pas le recepteur. Convention : {app}:{domain}:{action} (ex: catalog:product:selected). Eviter le shared state (couplage) sauf pour l'auth et le panier transversaux."},
{label:"Question 3",text:"Quelle approche de micro-frontend utilise Module Federation de webpack ?",options:["Des iframes independantes pour chaque micro-frontend","Le partage de modules JavaScript a l'execution entre applications deployees independamment","Un bundling unique de toutes les applications","Des Web Components natifs sans framework"],answer:1,explanation:"Module Federation permet a des builds webpack separees de partager des modules a l'execution (remote/host). Chaque app est deployee independamment mais peut importer des composants d'autres apps. Trade-off : couplage a webpack, complexite de versioning des dependances partagees."},
{label:"Question 4",text:"Quel est le role du shell application dans une architecture micro-frontend ?",options:["Generer le code de chaque micro-frontend au build time","Fournir l'infrastructure commune : routing, auth, layout, chargement des micro-frontends","Stocker toutes les donnees partagees","Compiler les micro-frontends en un seul bundle"],answer:1,explanation:"Le shell est le conteneur global : il gere le routing principal, l'authentification, le layout commun (header, footer), et le chargement dynamique des micro-frontends. C'est le hall d'entree du centre commercial."},
{label:"Question 5",text:"Quel probleme pose le partage de dependances (React, lodash) entre micro-frontends ?",options:["Les dependances ne peuvent pas etre partagees entre micro-frontends","Le versioning divergent peut causer des conflits a l'execution (deux versions de React) et le singleton problem","Le partage de dependances est toujours benefique sans inconvenient","Les dependances partagees empechent le deploiement independant"],answer:1,explanation:"Si l'app A utilise React 17 et l'app B React 18, le partage peut causer des conflits. Module Federation gere le versioning (singleton: true), mais c'est fragile. Trade-off : dupliquer les deps (plus de poids) vs partager (risque de conflit)."}
]},
// === 05-10 offline-first-pwa ===
{file:"quiz-05-10-offline-first-pwa.html",title:"Offline-first & PWA",sub:"Module 05 — Architecture Frontend",q:[
{label:"Question 1",text:"Quelle est la difference entre la strategie Cache First et Network First d'un Service Worker ?",options:["Cache First va au reseau en premier, Network First lit le cache en premier","Cache First sert depuis le cache et ne va au reseau qu'en cas de miss — ideal pour les assets statiques. Network First tente le reseau d'abord — ideal pour les donnees dynamiques","Les deux strategies sont identiques","Cache First ne fonctionne que pour les images"],answer:1,explanation:"Cache First = assets statiques (CSS, JS, images) qui changent rarement. Network First = appels API ou pages dynamiques ou la fraicheur est prioritaire. Trade-off : Cache First est ultra-rapide mais peut etre obsolete, Network First est toujours frais mais plus lent."},
{label:"Question 2",text:"Pourquoi Background Sync utilise-t-il IndexedDB et non localStorage ?",options:["localStorage est plus rapide qu'IndexedDB","IndexedDB est asynchrone, supporte les transactions, stocke des objets structures et a une capacite quasi illimitee — localStorage est synchrone et limite a ~5MB","IndexedDB est plus simple a utiliser","localStorage n'est pas supporte par les Service Workers"],answer:1,explanation:"IndexedDB : asynchrone (ne bloque pas le thread), transactions, objets structures, centaines de MB. localStorage : synchrone (bloque), strings uniquement, ~5MB. Pour une queue d'actions offline, seul IndexedDB est viable."},
{label:"Question 3",text:"Comment un Service Worker intercepte-t-il les requetes reseau ?",options:["En modifiant le code source de fetch() dans le navigateur","En ecoutant l'evenement 'fetch' et en decidant de repondre depuis le cache ou le reseau","En configurant un proxy HTTP dans les parametres du navigateur","En remplacant le DNS du navigateur"],answer:1,explanation:"Le Service Worker agit comme un proxy programmable entre l'application et le reseau. Il intercepte chaque requete via l'evenement 'fetch' et decide : repondre depuis le Cache API, aller au reseau, ou combiner les deux (SWR)."},
{label:"Question 4",text:"Qu'est-ce que le Background Sync et quel probleme resout-il ?",options:["La synchronisation automatique des bookmarks entre navigateurs","La mise en file d'attente des actions offline (mutations) pour les executer quand le reseau revient","Le telechargement de fichiers en arriere-plan","La synchronisation de l'horloge systeme avec un serveur NTP"],answer:1,explanation:"Background Sync permet d'enregistrer des actions (ex: envoyer un formulaire, passer une commande) dans une queue IndexedDB quand l'utilisateur est offline. Quand le reseau revient, le Service Worker les envoie automatiquement."},
{label:"Question 5",text:"Comment gerer les conflits quand deux appareils modifient les memes donnees offline ?",options:["Toujours prendre la version la plus recente (last-write-wins)","Implementer une strategie de conflict resolution : last-write-wins, merge automatique ou resolution manuelle par l'utilisateur","Les conflits ne peuvent pas se produire avec les Service Workers","Empecher les modifications offline pour eviter les conflits"],answer:1,explanation:"Last-write-wins est simple mais peut perdre des donnees. Le merge automatique (CRDT) est ideal mais complexe. La resolution manuelle (montrer les deux versions a l'utilisateur) est la plus sure. Le choix depend du domaine metier."}
]},
// === 06-01 fondamentaux-reseau ===
{file:"quiz-06-01-fondamentaux-reseau.html",title:"Fondamentaux reseau",sub:"Module 06 — Communication & Integration",q:[
{label:"Question 1",text:"Quel est le principal probleme de HTTP/1.1 resolu par HTTP/2 ?",options:["HTTP/1.1 ne supporte pas HTTPS","Le head-of-line blocking : HTTP/2 permet le multiplexing de plusieurs requetes sur une seule connexion TCP","HTTP/1.1 ne supporte pas les headers","HTTP/2 utilise un protocole binaire proprietaire"],answer:1,explanation:"HTTP/1.1 traite les requetes sequentiellement sur une connexion — une requete lente bloque les suivantes. HTTP/2 multiplexe les streams sur une seule connexion TCP. Trade-off : HTTP/2 souffre encore du HOL blocking au niveau TCP (resolu par HTTP/3/QUIC)."},
{label:"Question 2",text:"Pourquoi HTTP/3 utilise-t-il QUIC (UDP) plutot que TCP ?",options:["UDP est plus fiable que TCP","QUIC gere des streams independants — une perte sur un stream ne bloque pas les autres, et le handshake integre TLS 1.3","UDP est plus lent mais plus simple","HTTP/3 est compatible uniquement avec les navigateurs mobiles"],answer:1,explanation:"Avec TCP, une perte de paquet bloque TOUTES les streams multiplexees (HOL blocking au niveau transport). QUIC sur UDP gere chaque stream independamment. En bonus : 0-RTT pour les reconnexions. Trade-off : UDP est parfois bloque par des firewalls."},
{label:"Question 3",text:"Quelle est la difference entre SSE et WebSocket ?",options:["SSE est bidirectionnel, WebSocket est unidirectionnel","SSE est unidirectionnel (serveur→client) avec reconnexion automatique, WebSocket est bidirectionnel mais necessite une gestion manuelle de la reconnexion","Les deux sont identiques en termes de fonctionnalites","SSE utilise un protocole binaire, WebSocket utilise du texte"],answer:1,explanation:"SSE utilise HTTP standard (text/event-stream), supporte la reconnexion auto et passe les proxies/CDN. WebSocket utilise un protocole propre apres upgrade HTTP, permet la communication bidirectionnelle. SSE pour les notifications, WebSocket pour le chat."},
{label:"Question 4",text:"Qu'est-ce que le mTLS et en quoi differe-t-il du TLS classique ?",options:["mTLS chiffre les donnees deux fois pour plus de securite","Le TLS classique authentifie uniquement le serveur, le mTLS authentifie les deux parties (client ET serveur)","mTLS est une version allégée de TLS pour les mobiles","mTLS ne chiffre pas les donnees mais authentifie les parties"],answer:1,explanation:"Le mTLS (mutual TLS) ajoute l'authentification du client — le serveur verifie aussi le certificat du client. Utilise entre microservices pour empecher un attaquant dans le reseau de se faire passer pour un service. Gere par un service mesh en production."},
{label:"Question 5",text:"A quoi sert le TCP connection pooling dans une architecture microservices ?",options:["A limiter le nombre de microservices dans le cluster","A reutiliser les connexions TCP existantes pour eviter le cout du handshake a chaque requete","A compresser le trafic TCP entre services","A router le trafic TCP vers le bon service"],answer:1,explanation:"Chaque nouvelle connexion TCP necessite un handshake (1 RTT) + TLS (1-2 RTT). Le connection pooling maintient des connexions ouvertes et les reutilise. Trade-off : les connexions idle consomment de la memoire cote serveur."}
]},
// === 06-02 rest-avance ===
{file:"quiz-06-02-rest-avance.html",title:"REST avance",sub:"Module 06 — Communication & Integration",q:[
{label:"Question 1",text:"Quel est l'avantage de la pagination cursor par rapport a la pagination offset ?",options:["La pagination cursor est plus simple a implementer","La pagination cursor est stable (pas de doublons si des elements sont inseres) et performante en O(limit) constant, contrairement a l'offset qui degrade lineairement","La pagination cursor affiche le numero de page","La pagination cursor est toujours plus rapide pour les petites tables"],answer:1,explanation:"Offset : la DB scanne offset+limit lignes, et des insertions entre deux pages causent des doublons. Cursor : la DB cherche a partir du dernier element vu, en O(limit) constant. Trade-off : cursor ne permet pas de sauter a la 'page 7' — ideal pour le scroll infini, pas pour les tables admin."},
{label:"Question 2",text:"Qu'est-ce que HATEOAS et quel probleme resout-il ?",options:["Un format d'encodage binaire pour les API REST","L'API guide le client vers les actions possibles via des liens dans la reponse — le client decouvre les possibilites sans coder les URLs en dur","Un protocole de securite pour les webhooks","Un outil de documentation automatique des API"],answer:1,explanation:"HATEOAS (Hypermedia as the Engine of Application State) inclut des liens _links dans chaque reponse (self, publish, delete). Le client n'a pas besoin de construire les URLs. Trade-off : plus verbeux, peu adopte en pratique hors JSON-LD/Hydra."},
{label:"Question 3",text:"Pourquoi ne jamais mettre Vary: Cookie sur une reponse servie par un CDN ?",options:["Le header Vary n'est pas supporte par les CDN","Chaque utilisateur a un cookie unique, donc le CDN ne peut jamais servir une reponse cachee a un autre utilisateur — le hit ratio tombe a 0%","Les cookies sont trop volumineux pour le header Vary","Vary: Cookie desactive le chiffrement HTTPS"],answer:1,explanation:"Vary indique aux caches intermediaires quels headers influencent la reponse. Vary: Cookie signifie une version par cookie unique → aucun partage de cache possible. Solution : le Personalization Shell Pattern (page publique + fetch client-side)."},
{label:"Question 4",text:"Comment fonctionne l'ETag pour le cache conditionnel ?",options:["L'ETag force le navigateur a toujours recharger la page","Le serveur envoie un ETag (hash du contenu). Le client renvoie If-None-Match lors de la requete suivante. Si le contenu n'a pas change, le serveur repond 304 Not Modified","L'ETag remplace le header Content-Type","L'ETag est un token d'authentification"],answer:1,explanation:"ETag evite de retransmettre un contenu identique. Le client garde le hash, le serveur compare : si identique → 304 (pas de body, economie de bande passante). Trade-off : le serveur doit quand meme calculer le hash a chaque requete."},
{label:"Question 5",text:"Comment signaler la deprecation d'un endpoint API ?",options:["Supprimer l'endpoint immediatement sans prevenir","Ajouter un header Deprecation avec la date de sunset et un header Link vers la nouvelle version","Ralentir progressivement les temps de reponse de l'endpoint","Retourner une erreur 500 aleatoirement"],answer:1,explanation:"Le header Deprecation (RFC 8594) avec une date de sunset + un header Link vers le remplacement permet aux clients de migrer. Ajouter un warning dans la reponse et un sunset date dans la documentation. Supprimer seulement apres la date annoncee."}
]},
// === 06-03 graphql-grpc ===
{file:"quiz-06-03-graphql-grpc.html",title:"GraphQL & gRPC",sub:"Module 06 — Communication & Integration",q:[
{label:"Question 1",text:"Qu'est-ce que le probleme N+1 en GraphQL et comment le resoudre ?",options:["Un probleme de versioning des schemas GraphQL","Quand une requete pour N elements effectue 1 requete supplementaire par element pour resoudre une relation — resolu par DataLoader qui batche les requetes","Un probleme de securite lie aux injections GraphQL","Une limitation du nombre de champs dans une requete"],answer:1,explanation:"Pour 20 articles avec leur auteur : 1 requete pour les articles + 20 requetes pour chaque auteur = 21 requetes. DataLoader collecte tous les IDs dans le meme tick et fait UNE requete batchee (WHERE id IN (...)). On passe de 21 a 2 requetes."},
{label:"Question 2",text:"Quand choisir gRPC plutot que REST ou GraphQL ?",options:["Pour les API publiques accessibles depuis un navigateur","Pour la communication inter-services ou la performance est critique : serialisation binaire protobuf, HTTP/2, streaming natif","Quand on veut une API auto-documentee type Swagger","Pour les applications mobiles grand public"],answer:1,explanation:"gRPC est 5-10x plus compact que JSON (protobuf binaire), HTTP/2 obligatoire, 4 types de streaming. Ideal entre microservices. Trade-off : pas lisible par un humain, necessite gRPC-Web + proxy pour les navigateurs, pas de documentation Swagger."},
{label:"Question 3",text:"Quel est le principal risque de securite specifique a GraphQL ?",options:["Les injections SQL dans les resolvers","Les requetes profondement imbriquees qui consomment des ressources exponentielles (depth attack) et les requetes couteuses (cost attack)","GraphQL ne supporte pas l'authentification","Les mutations GraphQL sont toujours publiques"],answer:1,explanation:"Un attaquant peut envoyer une requete avec 20 niveaux d'imbrication ou demander des millions de champs. Solutions : limiter la profondeur (depth limiting), calculer le cout de la requete (cost analysis), et utiliser des persisted queries (whitelist)."},
{label:"Question 4",text:"Pourquoi les persisted queries ameliorent-elles la securite et la performance de GraphQL ?",options:["Elles persistent les resultats en cache indefiniment","Elles pre-enregistrent les requetes autorisees cote serveur — seuls des IDs de requetes sont envoyes, bloquant les requetes arbitraires","Elles compressent automatiquement les reponses","Elles persistent les connexions WebSocket"],answer:1,explanation:"Au lieu d'envoyer la requete GraphQL complete (string longue, analysable), le client envoie juste un hash/ID. Le serveur le mappe a la requete pre-enregistree. Avantages : securite (pas de requete arbitraire), performance (pas de parsing), bande passante (ID vs query string)."},
{label:"Question 5",text:"Quelle est la difference fondamentale entre REST et GraphQL en termes de fetching ?",options:["REST retourne toujours trop ou trop peu de donnees (over/under-fetching), GraphQL retourne exactement ce que le client demande","REST est toujours plus rapide que GraphQL","GraphQL ne supporte pas le caching HTTP","REST ne supporte pas les relations entre ressources"],answer:0,explanation:"REST : un endpoint = une structure fixe. Pour 5 infos differentes, 5 appels. GraphQL : une seule requete avec la liste exacte des champs voulus. Trade-off : GraphQL consomme plus de CPU serveur (parsing, validation, resolution) et le caching HTTP est plus complexe."}
]},
// === 06-04 websockets-realtime ===
{file:"quiz-06-04-websockets-realtime.html",title:"WebSockets & Real-time",sub:"Module 06 — Communication & Integration",q:[
{label:"Question 1",text:"Comment scaler les WebSockets sur plusieurs instances de serveur ?",options:["Les WebSockets scalent automatiquement avec le load balancer","Utiliser un Redis pub/sub adapter pour redistribuer les messages entre toutes les instances","Limiter les connexions a une seule instance","Utiliser HTTP long polling a la place"],answer:1,explanation:"Les rooms sont locales a chaque instance. Le Redis pub/sub adapter fait que chaque serveur publie sur Redis et s'abonne. Redis redistribue a toutes les instances, qui diffusent a leurs clients. Les rooms fonctionnent de maniere transparente."},
{label:"Question 2",text:"Pourquoi implementer un heartbeat/ping-pong sur une connexion WebSocket ?",options:["Pour accelerer le transfert des messages","Pour detecter les connexions mortes (client deconnecte sans fermer proprement) et liberer les ressources serveur","Pour compresser les messages WebSocket","Pour authentifier le client a chaque message"],answer:1,explanation:"Sans heartbeat, une connexion morte (client crash, perte reseau) reste ouverte cote serveur indefiniment, consommant memoire et file descriptors. Le ping/pong (toutes les 25-30s) detecte les connexions mortes et les ferme."},
{label:"Question 3",text:"Quand preferer SSE (Server-Sent Events) aux WebSockets ?",options:["Quand on a besoin de communication bidirectionnelle","Quand le flux est unidirectionnel serveur→client (notifications, flux d'evenements) et qu'on veut la reconnexion automatique et le passage CDN","Quand on a besoin de transfert binaire","Quand le client doit envoyer des messages frequents au serveur"],answer:1,explanation:"SSE est unidirectionnel, utilise HTTP standard (passe les proxies/CDN), supporte la reconnexion auto avec Last-Event-ID. Ideal pour notifications, live feeds. WebSocket est necessaire seulement si le client doit aussi envoyer des messages (chat, collaboration)."},
{label:"Question 4",text:"Comment gerer la reconnexion apres une coupure reseau en WebSocket ?",options:["Le navigateur reconnecte automatiquement les WebSockets","Implementer un retry avec exponential backoff et restaurer l'etat (rejoindre les rooms, renvoyer le dernier event ID)","Recharger la page entiere","Passer en mode HTTP polling definitivement"],answer:1,explanation:"Contrairement a SSE, la reconnexion WebSocket est manuelle. Il faut : detecter la deconnexion, retry avec backoff (1s, 2s, 4s...), re-authentifier, rejoindre les rooms, et demander les messages manques depuis le dernier event ID."},
{label:"Question 5",text:"Qu'est-ce que le concept de 'room' dans Socket.IO et a quoi sert-il ?",options:["Un espace de noms pour les fichiers statiques","Un canal logique qui permet de grouper des clients et de broadcaster des messages uniquement aux membres du groupe","Un mecanisme de rate limiting par groupe","Une salle de chat predifinie"],answer:1,explanation:"Une room est un groupe logique de connexions. Exemple : room 'article:123' contient tous les editeurs en train de modifier l'article 123. Un broadcast a la room n'atteint que ces editeurs, pas tous les clients connectes."}
]},
// === 06-05 event-driven-messaging ===
{file:"quiz-06-05-event-driven-messaging.html",title:"Event-driven & Message Queues",sub:"Module 06 — Communication & Integration",q:[
{label:"Question 1",text:"Comment securiser un webhook avec HMAC-SHA256 ?",options:["En chiffrant le body du webhook avec AES","Le serveur genere HMAC-SHA256(secret, body) dans un header X-Webhook-Signature — le recepteur recalcule et compare avec timingSafeEqual","En envoyant le webhook uniquement en HTTPS","En ajoutant un token JWT dans le body"],answer:1,explanation:"HMAC-SHA256 garantit l'authenticite (l'emetteur connait le secret) et l'integrite (le body n'a pas ete modifie). Utiliser crypto.timingSafeEqual() pour la comparaison evite les timing attacks."},
{label:"Question 2",text:"Pourquoi auto-desactiver un webhook apres 10 echecs consecutifs ?",options:["Pour economiser la bande passante du serveur","Pour eviter de surcharger le systeme avec des retries inutiles vers un endpoint mort — l'admin est notifie et peut reactiver manuellement","Les webhooks ne supportent que 10 tentatives","Pour respecter la norme HTTP"],answer:1,explanation:"Un endpoint mort genere des retries exponentiels indefiniment, consommant des ressources queue et reseau. Apres 10 echecs, on desactive et alerte. L'admin corrige le probleme et reactive. Trade-off : un endpoint temporairement down est desactive — d'ou les 10 tentatives."},
{label:"Question 3",text:"Quelle est la difference entre une message queue (Redis/BullMQ) et un event bus (Kafka) ?",options:["Ils sont identiques en termes de fonctionnalite","La queue delivre le message a UN consumer puis le supprime. Kafka conserve les messages (retention) et chaque consumer a son propre offset — plusieurs consumers peuvent lire le meme message","La queue est plus rapide que Kafka","Kafka ne supporte que les messages texte"],answer:1,explanation:"Queue (BullMQ) : le message est consomme et disparait. Un worker le traite. Kafka : le message est conserve (log append-only, retention configurable). Chaque consumer group a son propre offset. Trade-off : Kafka est plus complexe a operer mais offre le replay et le multi-consumer."},
{label:"Question 4",text:"A quoi sert AsyncAPI dans une architecture event-driven ?",options:["A generer automatiquement les consumers Kafka","A documenter les events (schema, channels, bindings) comme OpenAPI documente les API REST","A tester les webhooks en environnement de staging","A compresser les messages pour le transport"],answer:1,explanation:"AsyncAPI est le 'OpenAPI des events'. Il definit les channels, les schemas de messages, les bindings (Kafka, AMQP). Permet la generation de code, la documentation et la validation des contrats d'events entre equipes."},
{label:"Question 5",text:"Pourquoi utiliser un retry avec exponential backoff pour les webhooks ?",options:["Pour envoyer les webhooks plus rapidement","Pour laisser le temps au recepteur de se retablir sans le surcharger — delais croissants (1min, 5min, 30min...)","Pour respecter le rate limiting du recepteur","Pour chiffrer les retries avec des cles differentes"],answer:1,explanation:"Un retry immediat surcharge un serveur deja en difficulte. L'exponential backoff (1min, 5min, 30min, 1h, 4h...) laisse le temps de recuperer. Trade-off : le delai de livraison augmente avec chaque retry, mais la fiabilite aussi."}
]},
// === 06-06 api-gateway-bff ===
{file:"quiz-06-06-api-gateway-bff.html",title:"API Gateway & BFF",sub:"Module 06 — Communication & Integration",q:[
{label:"Question 1",text:"Quelle est la difference entre un API Gateway et un Service Mesh ?",options:["Ils font exactement la meme chose","L'API Gateway gere le trafic Nord-Sud (clients→services : routing, auth, rate limiting). Le Service Mesh gere le trafic Est-Ouest (service→service : mTLS, circuit breaker, observabilite)","L'API Gateway est pour le cloud, le Service Mesh pour le on-premise","Le Service Mesh remplace completement l'API Gateway"],answer:1,explanation:"L'API Gateway est le point d'entree unique pour les clients externes. Le Service Mesh (Istio, Linkerd) gere la communication interne entre services via des sidecar proxies. Les deux sont complementaires. Trade-off : le Service Mesh ajoute de la latence (sidecar) et de la complexite ops."},
{label:"Question 2",text:"Qu'est-ce que le pattern BFF (Backend for Frontend) et quel probleme resout-il ?",options:["Un framework frontend pour le server-side rendering","Un backend dedie a un client specifique (web, mobile) qui agrege les appels microservices et gere les tokens cote serveur","Un outil de build pour les applications frontend","Un pattern de caching pour les API publiques"],answer:1,explanation:"Le BFF agrege les appels a plusieurs microservices en une seule reponse adaptee au client, gere les tokens cote serveur (pas exposes au navigateur), et isole la logique de presentation. Chaque type de client a son propre BFF. Trade-off : plus de code backend a maintenir."},
{label:"Question 3",text:"Pourquoi le rate limiting est-il une responsabilite de l'API Gateway ?",options:["Le rate limiting ne peut etre implemente que dans un reverse proxy","Centraliser le rate limiting au gateway protege tous les services en amont et permet une politique uniforme par IP/tenant/API key","Le gateway a acces aux bases de donnees des services","Le rate limiting est impossible dans les services individuels"],answer:2,explanation:"Le gateway est le point de passage oblige de toutes les requetes. Le rate limiting y est applique avant que les services ne soient sollicites. Trade-off : le gateway est un Single Point of Failure — il doit etre hautement disponible."},
{label:"Question 4",text:"Quel est le risque principal d'un API Gateway mal concu ?",options:["Il consomme trop de memoire","Il devient un SPOF (Single Point of Failure) et un goulot d'etranglement si trop de logique metier y est placee","Il empeche le deploiement de nouveaux services","Il bloque les requetes HTTPS"],answer:1,explanation:"Le gateway doit rester lean : routing, auth, rate limiting, logging. Si on y ajoute de la logique metier, de la transformation de donnees complexe ou de l'aggregation, il devient un monolithe deguise. Trade-off : simplicite gateway vs fonctionnalites."},
{label:"Question 5",text:"Dans quel cas le BFF est-il preferable a un API Gateway generique ?",options:["Quand on a un seul type de client","Quand differents clients (web, mobile, admin) ont des besoins de donnees tres differents et qu'on veut eviter le 'one API to rule them all'","Quand on n'a pas de microservices","Quand on veut reduire le nombre de backends"],answer:1,explanation:"Le mobile a besoin de reponses agregees (une seule requete), le web peut faire plusieurs appels, l'admin a besoin de champs differents. Un BFF par client optimise chaque experience. Trade-off : multiplication des backends a maintenir."}
]}
];

quizzes.forEach(({file, title, sub, q}) => {
  const quiz = q.map((item, i) => ({...item, label: `Question ${i+1}`}));
  fs.writeFileSync(path.join(dir, file), tmpl(title, sub, quiz));
  console.log(`Created ${file}`);
});

console.log(`\nBatch 1 done: ${quizzes.length} files created`);
